    const reportStarts = typeof PERFORMANCE_REPORT_STARTS !== "undefined" ? PERFORMANCE_REPORT_STARTS : null;
    return Object.freeze({
      mode: "ASYNC_REPORT_START",
      completion_not_immediate: true,
      automatic_polling: false,
      status_operation: reportStarts?.[alias]?.next_operation || "performance_statistics_status"
    });
  }
  if (alias === "performance_statistics_status" || alias === "performance_vendor_statistics_status") {
    return Object.freeze({
      mode: "REPORT_STATUS_CHECK",
      may_be_pending: true,
      automatic_polling: false
    });
  }
  if (alias === "performance_statistics_report_download") {
    return Object.freeze({
      mode: "PREPARED_REPORT_DOWNLOAD",
      requires_prepared_report: true,
      automatic_polling: false
    });
  }
  return null;
}

function operationCard(alias, meta) {
  return Object.freeze({
    operation: alias,
    purpose: meta.purpose || "Read-only Ozon operation.",
    template: meta.template_runnable === false ? null : (meta.template || { operation: alias, params: {} }),
    template_runnable: meta.template_runnable !== false,
    required_parameters: Array.isArray(meta.required_parameters) ? Object.freeze([...meta.required_parameters]) : Object.freeze([]),
    section: meta.section || null,
    safety_class: meta.safety_class || "READ_SAFE",
    privacy_policy: meta.privacy_policy || "safe_projection",
    personal_data_setting_required_when_off: meta.policy_group === "personal_data_read",
    entitlement_key: meta.entitlement_key || null,
    entitlement: guidanceEntitlement(alias, meta),
    scenario_context: guidanceScenarioContext(alias),
    data_readiness: guidanceDataReadiness(alias, meta),
    workflow_role: meta.workflow_role || "single_read"
  });
}
